<?php /** @var array $flags @var array $audit @var $dups @var string $st */ ?>
<div class="tabs"><?php foreach (['open' => 'Open flags', 'resolved' => 'Resolved', 'all' => 'All'] as $k => $l): ?><a href="<?= e(url('admin/loyalty/security?status=' . $k)) ?>" class="<?= $st === $k ? 'on' : '' ?>"><?= $l ?></a><?php endforeach; ?></div>
<section class="apanel flush"><div class="tbl-wrap"><table class="tbl"><thead><tr><th>When</th><th>Customer</th><th>Type</th><th>Severity</th><th>Details</th><th></th></tr></thead><tbody>
<?php foreach ($flags as $f): ?><tr><td class="muted"><?= e(fmt_date($f->created_at)) ?></td><td><?= $f->user_id ? '<a href="' . e(url('admin/loyalty/members/' . $f->user_id)) . '">' . e($f->name) . '</a>' . ($f->loyalty_status === 'suspended' ? ' <span class="pill">suspended</span>' : '') : '—' ?></td><td><?= e(str_replace('_', ' ', $f->type)) ?></td><td><span class="pill <?= $f->severity === 'high' ? '' : 'ok' ?>"><?= e($f->severity) ?></span></td><td class="small"><?= e($f->details) ?></td>
<td class="r"><?php if ($f->status === 'open'): ?><form method="post" action="<?= e(url('admin/loyalty/flags/' . $f->id)) ?>" style="display:inline"><?= csrf_field() ?><input type="hidden" name="act" value="resolve"><button class="btn sm ghost">Resolve</button></form><?php if ($f->user_id && $f->loyalty_status !== 'suspended'): ?><form method="post" action="<?= e(url('admin/loyalty/flags/' . $f->id)) ?>" style="display:inline"><?= csrf_field() ?><input type="hidden" name="act" value="suspend"><button class="btn sm ghost danger" data-confirm="Suspend this loyalty account?">Suspend</button></form><?php endif; ?><?php endif; ?></td></tr>
<?php endforeach; ?><?php if (!$flags): ?><tr><td colspan="6" class="empty">Nothing suspicious detected.</td></tr><?php endif; ?></tbody></table></div></section>
<?php if (count($dups)): ?><section class="apanel"><h2>Possible duplicate accounts (same phone)</h2><?php foreach ($dups as $d): ?><p><?= e($d->phone) ?> — <?= (int) $d->c ?> accounts</p><?php endforeach; ?></section><?php endif; ?>
<section class="apanel"><h2>Admin activity &amp; audit log</h2><ul class="timeline"><?php foreach ($audit as $a): ?><li><span><b><?= e($a->action) ?></b> <?= $a->subject ? e($a->subject . ' #' . $a->subject_id) : '' ?> <small class="muted"><?= e(mb_substr((string) $a->details, 0, 160)) ?></small></span><small><?= e($a->actor) ?> · <?= e($a->ip) ?> · <?= e(fmt_date($a->created_at)) ?></small></li><?php endforeach; ?></ul>
<p class="muted small">Every points/cashback transaction is permanent in the ledger (Reports → Points earning / Cashback). Duplicate awards are impossible: every transaction has a unique reference. Transaction limits and approval thresholds are in Programme settings.</p></section>
